import {ChatInput} from '@github-ui/copilot-chat/components/ChatInput'
import {useChatManager} from '@github-ui/copilot-chat/CopilotChatManagerContext'
import {useCallback, useEffect, useState} from 'react'
import {SkeletonBox} from '@primer/react'
import {AgentIcon} from '@primer/octicons-react'
import {ReposSelector} from '@github-ui/repos-selector'
import {RefSelector} from '@github-ui/ref-selector'
import {isFeatureEnabled} from '@github-ui/feature-flags'
import type {Repository} from '@github-ui/current-repository'
import {useSearchParams} from '@github-ui/react-router'
import {SubAgentSelector} from './SubAgentSelector'
import {queryForRepos, type DropdownRepository} from '../hooks/useCopilotRepoFetching'

import {
  makeFileReference,
  makeSnippetReference,
  referenceName as getReferenceName,
} from '@github-ui/copilot-chat/utils/copilot-chat-helpers'
import type {CopilotChatRepo, LineRange} from '@github-ui/copilot-chat/utils/copilot-chat-types'
import styles from './SessionsNav.module.css'

export type CreateTaskReference = {
  path: string
  range?: LineRange
}

function makeFileOrSnippetReference({
  referenceRepo,
  reference,
}: {
  referenceRepo: CopilotChatRepo
  reference: CreateTaskReference
}) {
  if (reference.range) {
    return makeSnippetReference(reference.path, reference.range, referenceRepo)
  } else {
    return makeFileReference(reference.path, referenceRepo)
  }
}

export function NewTaskChatInput({
  handleUserSubmit,
  initialRepo,
  initialReference,
  hideRepoSelector,
}: {
  handleUserSubmit: (
    content: string,
    selectedRepo: DropdownRepository | null,
    selectedBranch: string,
    selectedSubAgent: string,
    fileReference?: string,
  ) => Promise<void>
  initialRepo?: Repository | null
  initialReference?: CreateTaskReference | null
  hideRepoSelector?: boolean
}) {
  // Use the chat manager to clear references when a new task is started
  const manager = useChatManager()
  const [selectedRepo, setSelectedRepo] = useState<DropdownRepository | null>(null)
  const [isLoadingRepos, setIsLoadingRepos] = useState(true)
  const [isLoadingBranch, setIsLoadingBranch] = useState(false)
  const [referenceRepo, setReferenceRepo] = useState<CopilotChatRepo | null>(null)
  const isBranchSelectionEnabled = isFeatureEnabled('copilot_immersive_agent_branch_selection')
  const [selectedBranch, setSelectedBranch] = useState<string>('')
  const [selectedSubAgent, setSelectedSubAgent] = useState<string | null>(null)
  const [reference, setReference] = useState<CreateTaskReference | null>(initialReference || null)
  const [searchParams] = useSearchParams()
  const branchParam = searchParams.get('branch')
  // Repo passed down from rails may not have defaultBranch to avoid making an extra db query on server side load
  // we can use the nwo from the initialRepo to set the selectedRepo
  const initialNwo = initialRepo && `${initialRepo.ownerLogin}/${initialRepo.name}`
  const nwoParam = searchParams.get('repo') ?? initialNwo

  const isSubAgentsEnabled = isFeatureEnabled('copilot_swe_agent_use_subagents')

  useEffect(() => {
    // Check if initialRepo exists and is not an empty object (useCurrentRepository returns an empty object by default, unfortunately)
    const isValidRepo = initialRepo && Object.keys(initialRepo).length > 0

    if (isValidRepo) {
      const nameWithOwner = `${initialRepo.ownerLogin}/${initialRepo.name}`
      setSelectedRepo({
        id: initialRepo.id,
        owner: initialRepo.ownerLogin,
        name: nameWithOwner,
        nameOnly: initialRepo.name,
        nameWithOwner,
        enabled: true,
        defaultBranch: initialRepo.defaultBranch,
        private: initialRepo.private,
      })
      const initialBranch = branchParam ?? initialRepo?.defaultBranch
      if (initialBranch) {
        setSelectedBranch(initialBranch)
      } else {
        // fetch the default branch from the server async
        const fetchDefaultBranch = async () => {
          try {
            const repositories = await queryForRepos(nameWithOwner)
            const repo = repositories.find(
              (repoData: {nameWithOwner: string}) => repoData.nameWithOwner === nameWithOwner,
            )
            if (repo) {
              setSelectedBranch(repo.defaultBranch)
            }
          } finally {
            setIsLoadingBranch(false)
          }
        }

        setIsLoadingBranch(true)
        fetchDefaultBranch()
      }
      manager.clearCurrentReferences()
      setIsLoadingRepos(false)
    } else {
      // Fetch the user's repositories as fallback
      const fetchRepos = async () => {
        try {
          const repos = await queryForRepos()

          // If the user passed in an nwo, check that it exists and is enabled
          let repo = nwoParam ? repos.find(r => r.nameWithOwner === nwoParam && r.enabled) : undefined

          // If no repo was found via nwo or nwo wasn't provided, find first enabled repo
          if (!repo) {
            repo = repos.find(r => r.enabled)
          }

          // If we found a repo, set it as the selected repo
          if (repo) {
            setSelectedRepo(repo)
            setSelectedBranch(branchParam ?? repo.defaultBranch)
          }
        } catch {
          // TODO: Show an error to the user that we failed to fetch their repos
        } finally {
          // Always set loading to false after fetching
          setIsLoadingRepos(false)
        }
      }

      fetchRepos()
    }
    // We only want this hook to run once since it triggers a fetch.
    // eslint-disable-next-line react-hooks/react-compiler
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  const onSubmit = useCallback(
    async (content: string) => {
      const referenceName =
        referenceRepo && reference
          ? getReferenceName(makeFileOrSnippetReference({referenceRepo, reference}))
          : undefined
      return handleUserSubmit(content, selectedRepo, selectedBranch, selectedSubAgent || '', referenceName)
    },
    [handleUserSubmit, selectedRepo, selectedBranch, selectedSubAgent, reference, referenceRepo],
  )

  // Fetch the reference repo
  const isFileReferenceEnabled = isFeatureEnabled('copilot_agent_tasks_btn_file_reference')
  useEffect(() => {
    if (!isFileReferenceEnabled) return

    if (initialRepo?.id != null) {
      ;(async () => {
        const repoResponse = await manager.service.fetchRepo(initialRepo.id)
        if (repoResponse.payload) setReferenceRepo(repoResponse.payload)
      })()
    }
  }, [initialRepo, manager, isFileReferenceEnabled])

  return (
    <ChatInput
      modes={[
        {
          name: 'Agent',
          icon: <AgentIcon />,
          submitLabel: 'Start task',
          placeholder: 'Describe a coding task to work on',
          textAreaAriaLabel: 'Coding task prompt',
        },
      ]}
      size="large"
      onSubmit={onSubmit}
      initialReference={referenceRepo && reference ? makeFileOrSnippetReference({reference, referenceRepo}) : undefined}
      extraToolbar={
        <div className={styles.extraToolbarActions}>
          {isLoadingRepos ? (
            <>
              {/* The height should match the populated button height and width should roughly match. */}
              <SkeletonBox height="32px" width="130px" />
            </>
          ) : hideRepoSelector ? null : (
            <ReposSelector
              repositoryLoader={queryForRepos}
              selectionVariant="single"
              selectAllOption={false}
              onSelect={(repo: DropdownRepository | undefined) => {
                if (!repo) return
                setSelectedRepo(repo)
                setSelectedBranch(repo.defaultBranch)
              }}
              currentSelection={selectedRepo || undefined}
              buttonText={selectedRepo?.nameWithOwner || 'Select repository'}
              width="medium"
              additionalButtonProps={{
                'aria-label': `Repository: ${selectedRepo?.nameWithOwner || 'Select repository'}`,
              }}
            />
          )}
          {isBranchSelectionEnabled &&
            (selectedRepo && !isLoadingBranch ? (
              <RefSelector
                // `cacheKey` is something consumers of this component usually get from a key derived from a current repository in the app payload
                // In our case, it's a static string since this page is not aware of any kind of current repository
                cacheKey="agent-sessions-ref-selector"
                canCreate={false}
                currentCommitish={selectedBranch}
                defaultBranch={selectedRepo.defaultBranch}
                owner={selectedRepo.owner}
                repo={selectedRepo.nameOnly}
                types={['branch']}
                selectedRefType="branch"
                closeOnSelect
                hideShowAll
                onSelectItem={ref => {
                  setSelectedBranch(ref)
                }}
              />
            ) : (
              <>
                {/* The height should match the populated button height and width should roughly match. */}
                <SkeletonBox height="32px" width="100px" />
              </>
            ))}
          {isSubAgentsEnabled && (
            <SubAgentSelector
              selectedAgent={selectedSubAgent}
              onSelect={setSelectedSubAgent}
              selectedRepo={selectedRepo}
            />
          )}
        </div>
      }
      submitDisabled={!selectedRepo || !selectedBranch}
      onRemoveReference={() => {
        setReference(null)
      }}
    />
  )
}

try{ NewTaskChatInput.displayName ||= 'NewTaskChatInput' } catch {}